import React, { useEffect, useState } from "react";
import UsageBarChart from "./components/UsageBarChart";
import UsagePieChart from "./components/UsagePieChart";
import ActivityList from "./components/ActivityList";

export default function App() {
  const [summary, setSummary] = useState([]);
  const [sessions, setSessions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  /* ---------------- DATA FETCHING ---------------- */
  useEffect(() => {
    const fetchData = async () => {
      try {
        const summaryRes = await fetch(
          "http://localhost:5000/api/analytics/summary"
        );
        if (!summaryRes.ok) throw new Error("Failed to fetch summary");
        const summaryData = await summaryRes.json();

        const sessionsRes = await fetch("http://localhost:5000/api/analytics");
        if (!sessionsRes.ok) throw new Error("Failed to fetch sessions");
        const sessionsData = await sessionsRes.json();

        setSummary(Array.isArray(summaryData) ? summaryData : []);
        setSessions(Array.isArray(sessionsData) ? sessionsData : []);
      } catch (err) {
        console.error(err);
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  /* ---------------- KPI CALCULATIONS ---------------- */
  const totalTime = summary.reduce((acc, item) => acc + (item.totalTime || 0), 0);
  const hours = Math.floor(totalTime / 60);
  const mins = totalTime % 60;

  const totalSites = summary.length || 0;

  const mostUsedSite =
    summary.length > 0
      ? summary.reduce((max, item) =>
          (item.totalTime || 0) > (max.totalTime || 0) ? item : max
        ).url
      : "N/A";

  const totalSessions = sessions.length || 0;

  /* ---------------- SAFE RENDER ---------------- */
  if (loading)
    return <p style={{ textAlign: "center", marginTop: "50px" }}>Loading dashboard...</p>;
  if (error)
    return (
      <p style={{ textAlign: "center", marginTop: "50px", color: "red" }}>
        {error}
      </p>
    );

  return (
    <div className="container">
      <h1>📊 Website Activity Dashboard</h1>

      {/* ================= KPI CARDS ================= */}
      <div className="kpi-grid">
        <div className="kpi-card">
          <h3>Total Time Spent</h3>
          <p>
            {hours} hr {mins} min
          </p>
        </div>

        <div className="kpi-card">
          <h3>Websites Visited</h3>
          <p>{totalSites}</p>
        </div>

        <div className="kpi-card">
          <h3>Most Used Site</h3>
          <p>{mostUsedSite}</p>
        </div>

        <div className="kpi-card">
          <h3>Total Sessions</h3>
          <p>{totalSessions}</p>
        </div>
      </div>

      {/* ================= CHARTS ================= */}
      <div className="card">
        <h2>Daily Usage (Bar)</h2>
        {summary.length > 0 ? (
          <UsageBarChart data={summary} />
        ) : (
          <p>No summary data available</p>
        )}
      </div>

      <div className="card">
        <h2>Usage Share (Pie)</h2>
        {summary.length > 0 ? (
          <UsagePieChart data={summary} />
        ) : (
          <p>No summary data available</p>
        )}
      </div>

      <div className="card">
        <h2>📱 App Activity</h2>
        {sessions.length > 0 ? (
          <ActivityList sessions={sessions} />
        ) : (
          <p>No session data available</p>
        )}
      </div>
    </div>
  );
}
